// Cookie-Editor export (no "id"/"storeId" null, sameSite lowercase).
const cookieEditorSample = `[{"domain":".1024terabox.com","expirationDate":1797999999,"hostOnly":false,"httpOnly":true,"name":"ndus","path":"/","sameSite":"lax","secure":true,"session":false,"storeId":null,"value":"redacted"}]`

// Playwright storage state.
const playwrightSample = `{"cookies":[{"name":"ndus","value":"pw","domain":".terabox.com","path":"/","expires":1797999999,"httpOnly":true,"secure":true,"sameSite":"Lax"},{"name":"sess","value":"s","domain":"www.terabox.com","path":"/","expires":-1,"httpOnly":false,"secure":false,"sameSite":"None"}],"origins":[]}`

func names(cs []*http.Cookie) string {
	var n []string
	for _, c := range cs {
		n = append(n, c.Name)
	}
	return strings.Join(n, ",")
}

func TestImportNetscape(t *testing.T) {
	r, err := ImportCookies(netscapeSample, teraboxDomains, cookieNow)
	if err != nil {
		t.Fatal(err)
	}
	if r.Format != "netscape" || names(r.Cookies) != "ndus,ndut_fmt,csrfToken,empty_value" {
		t.Fatalf("format %s cookies %s", r.Format, names(r.Cookies))
	}
	if r.Skipped != 1 || r.Expired != 1 {
		t.Fatalf("skipped %d expired %d", r.Skipped, r.Expired)
	}
	nd := r.Cookies[0]
	if nd.Domain != ".terabox.com" || !nd.Secure || nd.Expires.Unix() != 1798000000 || nd.Value != "YbcDEFredacted_0123456789" {
		t.Fatalf("ndus = %+v", nd)
	}
	if !r.Cookies[1].HttpOnly || r.Cookies[2].Domain != "www.terabox.com" || !r.Cookies[2].Expires.IsZero() {
		t.Fatalf("httpOnly/hostOnly parsing: %+v %+v", r.Cookies[1], r.Cookies[2])
	}
	if !strings.HasPrefix(r.Normalized, NetscapeHeader) || strings.Contains(r.Normalized, "SID") {
		t.Fatalf("normalized:\n%s", r.Normalized)
	}
	// The normalized text parses back to the same cookies.
	again, err := ImportCookies(r.Normalized, teraboxDomains, cookieNow)
	if err != nil || names(again.Cookies) != names(r.Cookies) || !again.Cookies[1].HttpOnly {
		t.Fatalf("re-parse: %v %s", err, names(again.Cookies))
	}
}

func TestImportNetscapeSpaces(t *testing.T) {
	// Tabs replaced by spaces after copying from a web page.
	in := ".terabox.com  TRUE  /  TRUE  1798000000  ndus  abc\nwww.terabox.com FALSE / FALSE 0 lang es"
	r, err := ImportCookies(in, teraboxDomains, cookieNow)
	if err != nil || names(r.Cookies) != "ndus,lang" {
		t.Fatalf("%v %v", err, r)
	}
}

func TestImportJSONShapes(t *testing.T) {
	cases := []struct {
		name, in, want string
	}{
		{"EditThisCookie", editThisCookieSample, "ndus,lang"},
		{"Cookie-Editor", cookieEditorSample, "ndus"},
		{"Playwright", playwrightSample, "ndus,sess"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			r, err := ImportCookies(c.in, teraboxDomains, cookieNow)
			if err != nil {
				t.Fatal(err)
			}
			if r.Format != "json" || names(r.Cookies) != c.want {
				t.Fatalf("got %s %s", r.Format, names(r.Cookies))
			}
			if !r.Cookies[0].HttpOnly || !r.Cookies[0].Secure || r.Cookies[0].Expires.IsZero() {
				t.Fatalf("flags lost: %+v", r.Cookies[0])
			}
		})
	}
	r, _ := ImportCookies(editThisCookieSample, teraboxDomains, cookieNow)
	if r.Cookies[1].Domain != "www.terabox.com" || !r.Cookies[1].Expires.IsZero() {
		t.Fatalf("hostOnly session cookie: %+v", r.Cookies[1])
	}
	if r.Skipped != 1 {
		t.Fatalf("mediafire cookie not skipped: %d", r.Skipped)
	}
}

func TestImportHeader(t *testing.T) {
	r, err := ImportCookies("Cookie: ndus=abc123; lang=es", teraboxDomains, cookieNow)
	if err != nil || r.Format != "header" || names(r.Cookies) != "ndus,lang" || r.Cookies[0].Domain != ".terabox.com" {
		t.Fatalf("%v %+v", err, r)
	}
	if _, err := ImportCookies("ndus=abc", nil, cookieNow); !errors.Is(err, ErrInvalidCookies) {
		t.Fatalf("header without domain: %v", err)
	}
}

func TestImportErrors(t *testing.T) {
	cases := []struct {
		name, in string
		want     error
	}{
		{"empty", "   \n", ErrInvalidCookies},
		{"garbage", "hello world\nthis is not a cookie file", ErrInvalidCookies},
		{"broken json", `[{"name": "a",`, ErrInvalidCookies},
		{"json no domain", `[{"name":"a","value":"b"}]`, ErrInvalidCookies},
		{"json not cookies", `{"foo": 1}`, ErrInvalidCookies},
		{"bad expiry", ".terabox.com\tTRUE\t/\tTRUE\tsoon\tndus\tx", ErrInvalidCookies},
		{"bad name", `[{"name":"a b","value":"x","domain":".terabox.com"}]`, ErrInvalidCookies},
		{"other hoster", `[{"name":"a","value":"x","domain":".mega.nz","expirationDate":1797999999}]`, ErrNoMatchingCookies},
		{"all expired", ".terabox.com\tTRUE\t/\tTRUE\t1600000000\tndus\tx", ErrCookiesExpired},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			_, err := ImportCookies(c.in, teraboxDomains, cookieNow)
			if !errors.Is(err, c.want) {
				t.Fatalf("got %v, want %v", err, c.want)
			}
		})
	}
	_, err := ImportCookies(`[{"name":"a","value":"x","domain":".mega.nz"}]`, teraboxDomains, cookieNow)
	if !strings.Contains(err.Error(), "mega.nz") {
		t.Fatalf("error should name the domains found: %v", err)
	}
}

func TestImportMillisecondsAndDedupe(t *testing.T) {
	in := `[{"name":"a","value":"1","domain":".terabox.com","expirationDate":1797999999000},
	        {"name":"a","value":"2","domain":".terabox.com","expirationDate":1797999999}]`
	r, err := ImportCookies(in, teraboxDomains, cookieNow)
	if err != nil {
		t.Fatal(err)
	}
	if len(r.Cookies) != 1 || r.Cookies[0].Value != "2" || r.Cookies[0].Expires.Year() != 2026 {
		t.Fatalf("%+v", r.Cookies)
	}
	if r.EarliestExpiry.IsZero() {
		t.Fatal("earliest expiry not reported")
	}
}

func TestLoadCookiesIntoJar(t *testing.T) {
	r, err := ImportCookies(netscapeSample, teraboxDomains, cookieNow)
	if err != nil {
		t.Fatal(err)
	}
	jar, _ := cookiejar.New(nil)
	u, _ := url.Parse("https://www.terabox.com/sharing/link?surl=x")
	n, err := LoadCookies(jar, u, r.Normalized, cookieNow)
	if err != nil {
		t.Fatal(err)
	}
	if n != 4 {
		t.Fatalf("set %d cookies", n)
	}
	got := jar.Cookies(u)
	if !strings.Contains(CookieHeader(got), "ndus=YbcDEFredacted_0123456789") || !strings.Contains(CookieHeader(got), "csrfToken=") {
		t.Fatalf("jar cookies: %s", names(got))
	}
	// Host-only csrfToken must not leak to the apex domain.
	apex, _ := url.Parse("https://terabox.com/")
	jar2, _ := cookiejar.New(nil)
	SetJarCookies(jar2, apex, r.Cookies)
	if strings.Contains(names(jar2.Cookies(apex)), "csrfToken") {
		t.Fatal("host-only cookie applied to another host")
	}
	// Retarget for a mirror domain.
	mirror, _ := url.Parse("https://www.1024terabox.com/s/1abc")
	jar3, _ := cookiejar.New(nil)
	if n := SetJarCookies(jar3, mirror, RetargetCookies(r.Cookies[:1], "1024terabox.com")); n != 1 {
		t.Fatalf("retarget set %d", n)
	}
	if names(jar3.Cookies(mirror)) != "ndus" {
		t.Fatalf("mirror cookies %s", names(jar3.Cookies(mirror)))
	}
}
